from PIL import Image
import numpy as np
im=np.array(Image.open('first_frame.png').convert('RGB'))
# Print 8x8 blocks average as grayscale level 0-9 and hue letter
for mode in ['gray','rgb']:
 print('\\n',mode)
 for y in range(0,144,8):
  row=''
  for x in range(0,256,8):
   p=im[y:y+8,x:x+8].mean((0,1)); v=p.mean()
   if mode=='gray': row+=str(int(np.clip(v//26,0,9)))
   else:
    mx=p.max();mn=p.min()
    if mx-mn<8: c='K' if mx<60 else ('w' if mx>190 else 'g')
    else: c='R' if p[0]==mx else ('G' if p[1]==mx else 'B')
    row+=c
  print(f'{y:3}',row)
# per block rgb table 16x16
print('\\n16-block RGB')
for y in range(0,144,16):
 print('y',y, ['%02x%02x%02x'%tuple(im[y:y+16,x:x+16].mean((0,1)).astype(int)) for x in range(0,256,16)])
